-- Schema of main c5ace46, before the queue/workspace/permissions migrations.
CREATE TABLE IF NOT EXISTS `chats_v2` (`chat_id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `title` TEXT NOT NULL, `enabled_platform` TEXT NOT NULL, `active_platform` TEXT NOT NULL DEFAULT '', `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, `is_favorite` INTEGER NOT NULL DEFAULT 0, `is_archived` INTEGER NOT NULL DEFAULT 0, `draft_text` TEXT, `draft_updated_at` INTEGER, `is_title_customized` INTEGER NOT NULL DEFAULT 0, `conversation_mode` TEXT NOT NULL DEFAULT 'STANDARD');
CREATE INDEX IF NOT EXISTS `index_chats_v2_archived_favorite_updated` ON `chats_v2` (`is_archived`, `is_favorite`, `updated_at`);
CREATE INDEX IF NOT EXISTS `index_chats_v2_archived_updated` ON `chats_v2` (`is_archived`, `updated_at`);
CREATE TABLE IF NOT EXISTS `messages_v2` (`message_id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `chat_id` INTEGER NOT NULL, `thoughts` TEXT NOT NULL, `content` TEXT NOT NULL, `attachments` TEXT NOT NULL, `revisions` TEXT NOT NULL DEFAULT '[]', `active_revision_index` INTEGER NOT NULL DEFAULT -1, `linked_message_id` INTEGER NOT NULL, `platform_type` TEXT, `current_run_id` TEXT, `created_at` INTEGER NOT NULL, `timeline` TEXT NOT NULL DEFAULT '[]', `is_favorite` INTEGER NOT NULL DEFAULT 0, `timestamp` INTEGER NOT NULL DEFAULT 0, `combined_sources` TEXT NOT NULL DEFAULT '[]', FOREIGN KEY(`chat_id`) REFERENCES `chats_v2`(`chat_id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_messages_v2_chat_id` ON `messages_v2` (`chat_id`);
CREATE INDEX IF NOT EXISTS `index_messages_v2_chat_id_created_at_message_id` ON `messages_v2` (`chat_id`, `created_at`, `message_id`);
CREATE INDEX IF NOT EXISTS `index_messages_v2_is_favorite` ON `messages_v2` (`is_favorite`);
CREATE TABLE IF NOT EXISTS `platform_v2` (`platform_id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `uid` TEXT NOT NULL, `name` TEXT NOT NULL, `compatible_type` TEXT NOT NULL, `enabled` INTEGER NOT NULL DEFAULT 1, `api_url` TEXT NOT NULL, `token` TEXT, `secret_ref` TEXT, `model` TEXT NOT NULL, `temperature` REAL, `top_p` REAL, `top_k` INTEGER, `max_tokens` INTEGER, `accelerator` TEXT, `system_prompt` TEXT, `stream` INTEGER NOT NULL, `reasoning` INTEGER NOT NULL, `timeout` INTEGER NOT NULL, `max_tool_calls` INTEGER NOT NULL DEFAULT 2147483647, `harassment_safety_threshold` TEXT NOT NULL DEFAULT 'BLOCK_NONE', `hate_speech_safety_threshold` TEXT NOT NULL DEFAULT 'BLOCK_NONE', `sexually_explicit_safety_threshold` TEXT NOT NULL DEFAULT 'BLOCK_NONE', `dangerous_content_safety_threshold` TEXT NOT NULL DEFAULT 'BLOCK_NONE', `open_router_routing` TEXT, `disable_all_tools` INTEGER NOT NULL DEFAULT 0, `disable_remote_tools` INTEGER NOT NULL DEFAULT 0, `disable_local_tools` INTEGER NOT NULL DEFAULT 0, `ollama_options` TEXT, `labels` TEXT, `is_favorite` INTEGER NOT NULL DEFAULT 0, `batch_mode` INTEGER NOT NULL DEFAULT 0, `batch_api_url` TEXT, `provider_connection_uid` TEXT);
CREATE TABLE IF NOT EXISTS `chat_platform_model_v2` (`chat_id` INTEGER NOT NULL, `platform_uid` TEXT NOT NULL, `model` TEXT NOT NULL, `updated_at` INTEGER NOT NULL, PRIMARY KEY(`chat_id`, `platform_uid`), FOREIGN KEY(`chat_id`) REFERENCES `chats_v2`(`chat_id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE IF NOT EXISTS `tool_connections` (`connection_uid` TEXT NOT NULL, `name` TEXT NOT NULL, `alias` TEXT NOT NULL, `type` TEXT NOT NULL, `endpoint_url` TEXT, `auth_type` TEXT NOT NULL, `secret_ref` TEXT, `oauth_client_id` TEXT, `allow_cleartext` INTEGER NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, PRIMARY KEY(`connection_uid`));
CREATE UNIQUE INDEX IF NOT EXISTS `index_tool_connections_alias` ON `tool_connections` (`alias`);
CREATE TABLE IF NOT EXISTS `agent_tool_bindings` (`binding_uid` TEXT NOT NULL, `profile_uid` TEXT NOT NULL, `connection_uid` TEXT, `tool_name` TEXT NOT NULL, `created_at` INTEGER NOT NULL, PRIMARY KEY(`binding_uid`), FOREIGN KEY(`connection_uid`) REFERENCES `tool_connections`(`connection_uid`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_agent_tool_bindings_profile_uid` ON `agent_tool_bindings` (`profile_uid`);
CREATE INDEX IF NOT EXISTS `index_agent_tool_bindings_connection_uid` ON `agent_tool_bindings` (`connection_uid`);
CREATE UNIQUE INDEX IF NOT EXISTS `index_agent_tool_bindings_profile_uid_connection_uid_tool_name` ON `agent_tool_bindings` (`profile_uid`, `connection_uid`, `tool_name`);
CREATE TABLE IF NOT EXISTS `agent_runs` (`run_id` TEXT NOT NULL, `chat_id` INTEGER NOT NULL, `user_message_id` INTEGER NOT NULL, `assistant_message_id` INTEGER NOT NULL, `profile_uid` TEXT NOT NULL, `provider_snapshot` TEXT NOT NULL, `model_snapshot` TEXT NOT NULL, `status` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `started_at` INTEGER, `completed_at` INTEGER, `terminal_error` TEXT, `gateway_job_id` TEXT, `gateway_base_url` TEXT, `gateway_last_sequence` INTEGER NOT NULL, `input_tokens` INTEGER, `output_tokens` INTEGER, `total_tokens` INTEGER, PRIMARY KEY(`run_id`), FOREIGN KEY(`chat_id`) REFERENCES `chats_v2`(`chat_id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`user_message_id`) REFERENCES `messages_v2`(`message_id`) ON UPDATE NO ACTION ON DELETE CASCADE , FOREIGN KEY(`assistant_message_id`) REFERENCES `messages_v2`(`message_id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_agent_runs_chat_id` ON `agent_runs` (`chat_id`);
CREATE INDEX IF NOT EXISTS `index_agent_runs_user_message_id` ON `agent_runs` (`user_message_id`);
CREATE INDEX IF NOT EXISTS `index_agent_runs_assistant_message_id` ON `agent_runs` (`assistant_message_id`);
CREATE INDEX IF NOT EXISTS `index_agent_runs_status` ON `agent_runs` (`status`);
CREATE INDEX IF NOT EXISTS `index_agent_runs_gateway_job_id` ON `agent_runs` (`gateway_job_id`);
CREATE TABLE IF NOT EXISTS `tool_events` (`event_id` TEXT NOT NULL, `run_id` TEXT NOT NULL, `sequence` INTEGER NOT NULL, `call_id` TEXT NOT NULL, `connection_uid_snapshot` TEXT, `connection_name_snapshot` TEXT, `tool_name` TEXT NOT NULL, `model_tool_name` TEXT NOT NULL, `arguments` TEXT NOT NULL, `result` TEXT, `result_type` TEXT, `status` TEXT NOT NULL, `is_error` INTEGER NOT NULL, `started_at` INTEGER, `completed_at` INTEGER, `error` TEXT, PRIMARY KEY(`event_id`), FOREIGN KEY(`run_id`) REFERENCES `agent_runs`(`run_id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_tool_events_run_id` ON `tool_events` (`run_id`);
CREATE UNIQUE INDEX IF NOT EXISTS `index_tool_events_run_id_sequence` ON `tool_events` (`run_id`, `sequence`);
CREATE TABLE IF NOT EXISTS `local_models` (`catalog_entry_id` TEXT NOT NULL, `commit_hash` TEXT NOT NULL, `file_name` TEXT NOT NULL, `relative_directory` TEXT NOT NULL, `total_bytes` INTEGER NOT NULL, `status` TEXT NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, PRIMARY KEY(`catalog_entry_id`));
CREATE TABLE IF NOT EXISTS `openrouter_batch_cache` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `cache_key` TEXT NOT NULL, `response_content` TEXT NOT NULL, `timestamp` INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS `index_openrouter_batch_cache_cache_key` ON `openrouter_batch_cache` (`cache_key`);
CREATE INDEX IF NOT EXISTS `index_openrouter_batch_cache_timestamp` ON `openrouter_batch_cache` (`timestamp`);
CREATE TABLE IF NOT EXISTS `provider_connections` (`connection_uid` TEXT NOT NULL, `name` TEXT NOT NULL, `compatible_type` TEXT NOT NULL, `api_url` TEXT NOT NULL, `secret_ref` TEXT, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL, PRIMARY KEY(`connection_uid`));
CREATE INDEX IF NOT EXISTS `index_provider_connections_compatible_type` ON `provider_connections` (`compatible_type`);
CREATE INDEX IF NOT EXISTS `index_provider_connections_compatible_type_api_url` ON `provider_connections` (`compatible_type`, `api_url`);
